 public sealed partial class ModernLauncher {
  void SignedIn(Dictionary<string,object> result){token=Packs.Text(result,"token");username=Packs.Text(Packs.Dict(result["user"]),"username");Save();Localize();}
  async Task<Dictionary<string,object>> Firebase(string key,string operation,object body){
   try{using(var c=Client()){c.Headers["Content-Type"]="application/json; charset=utf-8";string text=await c.UploadStringTaskAsync("https://identitytoolkit.googleapis.com/v1/accounts:"+operation+"?key="+Uri.EscapeDataString(key),"POST",Packs.Json.Serialize(body));return Packs.Json.Deserialize<Dictionary<string,object>>(text);}}
   catch(WebException e){string message=L("Не удалось войти. Проверь email и пароль.","Could not sign in. Check your email and password.","Не вдалося увійти. Перевір email і пароль.");try{using(var reader=new StreamReader(e.Response.GetResponseStream(),Encoding.UTF8)){var result=Packs.Json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());string code=Packs.Text(Packs.Dict(result["error"]),"message");if(code.Contains("EMAIL_EXISTS"))message=L("Email уже зарегистрирован. Нажми «Войти».","Email already registered. Select Sign in.","Email уже зареєстровано. Натисни «Увійти».");else if(code.Contains("TOO_MANY"))message=L("Слишком много попыток. Попробуй позже.","Too many attempts. Try later.","Забагато спроб. Спробуй пізніше.");else if(code.Contains("OPERATION_NOT_ALLOWED"))message=L("Email/Password ещё не включён в Firebase.","Email/Password is not enabled in Firebase yet.","Email/Password ще не ввімкнено у Firebase.");}}catch{}throw new InvalidOperationException(message);}
  }
  bool IsEmail(string value){try{var address=new System.Net.Mail.MailAddress(value);return address.Address==value&&value.Length<=254;}catch{return false;}}
  async Task Account(bool registration=false,string initialEmail=""){
   if(server==""){View("Settings");Offline();return;}
   if(token!=""){if(MessageBox.Show(Window,"@"+username+"\n"+L("Выйти из аккаунта?","Sign out?","Вийти з акаунта?"),"SoundSpace",MessageBoxButton.YesNo)==MessageBoxResult.Yes){token="";username="";Save();Localize();}return;}
   var providers=await Api("/api/auth/providers");var github=Packs.Dict(providers["github"]);var emailProvider=Packs.Dict(providers["email"]);bool githubReady=Convert.ToBoolean(github["enabled"]),emailReady=Convert.ToBoolean(emailProvider["enabled"]);string firebaseKey=Packs.Text(emailProvider,"apiKey");
   StackPanel panel;var d=Dialog(registration?L("Создать аккаунт","Create an account","Створити акаунт"):L("Войти в SoundSpace","Sign in to SoundSpace","Увійти в SoundSpace"),out panel);d.Width=510;d.Height=710;bool switchMode=false;
   var error=new TextBlock {TextWrapping=TextWrapping.Wrap,Foreground=Orange,Margin=new Thickness(0,14,0,0)};
   var githubButton=BA("GitHub  ↗",async()=>{
    var flow=await Api("/api/auth/github/start",new{});StackPanel prompt;var auth=Dialog("GitHub",out prompt);auth.Height=370;
    prompt.Children.Add(new TextBlock {Text=L("Введи этот код на странице GitHub:","Enter this code on GitHub:","Введи цей код на сторінці GitHub:"),TextWrapping=TextWrapping.Wrap});
    var code=new TextBox {Text=Packs.Text(flow,"userCode"),IsReadOnly=true,FontSize=26,Margin=new Thickness(0,16,0,16),HorizontalContentAlignment=HorizontalAlignment.Center};prompt.Children.Add(code);
    string url=Packs.Text(flow,"verificationUri");if(url!="https://github.com/login/device")throw new InvalidDataException("Unexpected GitHub URL");
    prompt.Children.Add(B(L("Открыть GitHub","Open GitHub","Відкрити GitHub"),()=>Process.Start(new ProcessStartInfo(url){UseShellExecute=true}),true));
    var note=new TextBlock {Text=L("Ожидаю подтверждения…","Waiting for authorization…","Очікую підтвердження…"),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,14,0,0)};prompt.Children.Add(note);
    var cancel=new CancellationTokenSource();auth.Closed+=(s,e)=>cancel.Cancel();bool completed=false;
    auth.ContentRendered+=async(s,e)=>{try{int interval=Convert.ToInt32(flow["interval"]);DateTime deadline=DateTime.UtcNow.AddSeconds(Convert.ToInt32(flow["expiresIn"]));while(DateTime.UtcNow<deadline){await Task.Delay(interval*1000,cancel.Token);var result=await Api("/api/auth/github/poll",new{flow=Packs.Text(flow,"flow")});object pending;if(result.TryGetValue("pending",out pending)&&Convert.ToBoolean(pending)){interval=Convert.ToInt32(result["interval"]);continue;}SignedIn(result);completed=true;auth.Close();break;}if(!completed&&!cancel.IsCancellationRequested)note.Text=L("Код истёк. Закрой окно и начни вход заново.","Code expired. Close and start sign-in again.","Код завершився. Закрий вікно та почни знову.");}catch(OperationCanceledException){}catch(Exception ex){note.Text=ex.Message;}};
    auth.ShowDialog();if(completed)d.Close();
   },true);githubButton.HorizontalAlignment=HorizontalAlignment.Stretch;githubButton.IsEnabled=githubReady;panel.Children.Add(githubButton);
   if(!githubReady)panel.Children.Add(new TextBlock {Text=L("GitHub ещё настраивается владельцем.","GitHub is not configured yet.","GitHub ще налаштовується власником."),Foreground=Muted,Margin=new Thickness(0,8,0,12)});
   panel.Children.Add(new TextBlock {Text=L("или email и пароль","or email and password","або email і пароль"),Foreground=Muted,Margin=new Thickness(0,20,0,12)});
   var email=new TextBox {Text=initialEmail,Margin=new Thickness(0,0,0,12),ToolTip="Email"};panel.Children.Add(new TextBlock {Text="Email",Foreground=Muted,Margin=new Thickness(0,0,0,7)});panel.Children.Add(email);
   panel.Children.Add(new TextBlock {Text=L("Пароль (10–128 символов)","Password (10–128 characters)","Пароль (10–128 символів)"),Foreground=Muted,Margin=new Thickness(0,0,0,7)});var password=new PasswordBox {Margin=new Thickness(0,0,0,12)};panel.Children.Add(password);var confirm=new PasswordBox {Margin=new Thickness(0,0,0,12)};if(registration){panel.Children.Add(new TextBlock {Text=L("Повтори пароль","Confirm password","Повтори пароль"),Foreground=Muted,Margin=new Thickness(0,0,0,7)});panel.Children.Add(confirm);}string verificationToken="";
   Func<string,Task> submit=async operation=>{try{if(!IsEmail(email.Text.Trim()))throw new InvalidOperationException(L("Введи корректный email.","Enter a valid email address.","Введи коректний email."));if(password.Password.Length<10||password.Password.Length>128)throw new InvalidOperationException(AccountValidation.Validate("valid_user",password.Password,language));if(operation=="signUp"&&password.Password!=confirm.Password)throw new InvalidOperationException(L("Пароли не совпадают.","Passwords do not match.","Паролі не збігаються."));error.Text="";var result=await Firebase(firebaseKey,operation,new{email=email.Text.Trim(),password=password.Password,returnSecureToken=true});verificationToken=Packs.Text(result,"idToken");if(operation=="signUp"){await Firebase(firebaseKey,"sendOobCode",new{requestType="VERIFY_EMAIL",idToken=verificationToken});error.Text=L("Письмо отправлено. Подтверди email и нажми «Войти».","Verification sent. Confirm your email, then select Sign in.","Лист надіслано. Підтвердь email і натисни «Увійти».");return;}SignedIn(await Api("/api/auth/firebase",new{idToken=verificationToken}));d.Close();}catch(Exception ex){error.Text=ex.Message;}};
   var actions=new WrapPanel();var login=BA(L("Войти","Sign in","Увійти"),()=>submit("signInWithPassword"),true);var register=BA(L("Регистрация","Register","Реєстрація"),()=>submit("signUp"));login.IsEnabled=register.IsEnabled=emailReady;actions.Children.Add(registration?register:login);panel.Children.Add(actions);
   var reset=BA(L("Забыли пароль?","Forgot password?","Забули пароль?"),async()=>{try{if(!IsEmail(email.Text.Trim()))throw new InvalidOperationException("Enter your email first.");await Firebase(firebaseKey,"sendOobCode",new{requestType="PASSWORD_RESET",email=email.Text.Trim()});error.Text=L("Если аккаунт существует, письмо для сброса отправлено.","If the account exists, a reset email has been sent.","Якщо акаунт існує, лист для скидання надіслано.");}catch(Exception ex){error.Text=ex.Message;}});reset.IsEnabled=emailReady;if(!registration)panel.Children.Add(reset);
   var resend=BA(L("Отправить подтверждение ещё раз","Resend verification","Надіслати підтвердження ще раз"),async()=>{try{if(verificationToken=="")throw new InvalidOperationException(L("Сначала введи email и пароль и нажми «Войти».","First enter your email and password and select Sign in.","Спочатку введи email і пароль та натисни «Увійти»."));await Firebase(firebaseKey,"sendOobCode",new{requestType="VERIFY_EMAIL",idToken=verificationToken});error.Text=L("Письмо отправлено.","Email sent.","Лист надіслано.");}catch(Exception ex){error.Text=ex.Message;}});resend.IsEnabled=emailReady;if(!registration)panel.Children.Add(resend);
   if(!emailReady)panel.Children.Add(new TextBlock {Text=L("Email ожидает подключения Firebase.","Email sign-in is awaiting Firebase setup.","Email очікує підключення Firebase."),Foreground=Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,0)});
   panel.Children.Add(B(registration?L("Уже есть аккаунт? Войти","Already registered? Sign in","Уже є акаунт? Увійти"):L("Нет аккаунта? Зарегистрироваться","New here? Create an account","Немає акаунта? Зареєструватися"),()=>{switchMode=true;d.Close();}));if(!registration)panel.Children.Add(B(L("Вход в старый аккаунт по логину","Legacy username sign-in","Вхід у старий акаунт за логіном"),()=>LegacyAccount(d)));
   panel.Children.Add(error);d.ShowDialog();if(switchMode)await Account(!registration,email.Text.Trim());
  }
  void LegacyAccount(Window parent){StackPanel panel;var d=Dialog(L("Старый аккаунт","Legacy account","Старий акаунт"),out panel);d.Owner=parent;var name=new TextBox {Margin=new Thickness(0,0,0,12)};var password=new PasswordBox {Margin=new Thickness(0,0,0,12)};panel.Children.Add(new TextBlock {Text="Username",Foreground=Muted});panel.Children.Add(name);panel.Children.Add(new TextBlock {Text="Password",Foreground=Muted});panel.Children.Add(password);var error=new TextBlock {Foreground=Orange,TextWrapping=TextWrapping.Wrap};panel.Children.Add(BA(L("Войти","Sign in","Увійти"),async()=>{try{var result=await Api("/api/auth/login",new{username=name.Text.Trim(),password=password.Password});SignedIn(result);d.Close();parent.Close();}catch(Exception ex){error.Text=ex.Message;}},true));panel.Children.Add(error);d.ShowDialog();}
  async Task MyPublications(){var host=C<WrapPanel>("MyPackCards");host.Children.Clear();if(token==""){bool previous=busy;busy=false;try{await Account();}finally{busy=previous;}if(token=="")return;}var result=await Api("/api/me/packs");int index=0;foreach(var value in (IEnumerable)result["packs"]){var item=Packs.Dict(value);string id=Packs.Text(item,"id");var card=Card(Packs.Text(item,"name"),"@"+Packs.Text(item,"author"),Packs.Text(item,"category"),index++,async()=>PreviewPack(await Download(item)),async()=>Use(await Download(item),true));card.Width=300;var body=card.Child as StackPanel;body.Children.Add(BA(L("Удалить из мастерской","Delete from workshop","Видалити з майстерні"),async()=>{if(MessageBox.Show(Window,L("Удалить этот пак из общего каталога?","Delete this pack from the shared catalog?","Видалити цей пак зі спільного каталогу?")+"\n"+Packs.Text(item,"name"),"SoundSpace",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;await Api("/api/packs/"+id,null,"DELETE");await MyPublications();await Refresh(false);}));host.Children.Add(card);}if(host.Children.Count==0)host.Children.Add(new TextBlock {Text=L("Ты ещё не публиковал паки.","You have not published any packs yet.","Ти ще не публікував паки."),Foreground=Muted});}
 }
